<?php
$query = trim((string) ($_GET['q'] ?? ''));
$gender = trim((string) ($_GET['gender'] ?? ''));
$roomType = trim((string) ($_GET['room_type'] ?? ''));
$maxPrice = (int) ($_GET['max_price'] ?? 0);
$pgs = PG::search($query, $gender ?: null, $roomType ?: null, $maxPrice ?: null);
?><!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Find PG</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:linear-gradient(180deg,#f8faff,#eef4ff);font-family:Inter,Arial,sans-serif;color:#111827}.page{max-width:1280px;margin:0 auto;padding:28px 18px 70px}.search-header{background:linear-gradient(135deg,rgba(79,70,229,.08),rgba(20,184,166,.1));border:1px solid rgba(15,23,42,.06);border-radius:28px;padding:26px}.search-form{background:#fff;border:1px solid rgba(15,23,42,.08);border-radius:18px;padding:12px;display:flex;gap:12px;margin-top:18px}.search-form input{border:0;background:transparent;padding:14px 12px;width:100%}.primary-btn{background:linear-gradient(135deg,#4f46e5,#312e81);border:0;color:#fff;border-radius:14px;padding:14px 24px;font-weight:700}.content-grid{display:grid;grid-template-columns:280px 1fr;gap:24px;margin-top:26px}.filters,.pg-card{background:#fff;border:1px solid rgba(15,23,42,.08);border-radius:22px;padding:22px;box-shadow:0 20px 30px rgba(15,23,42,.04)}.filter-section{padding-bottom:18px;border-bottom:1px solid #eef0f4;margin-bottom:18px}.filter-options{display:grid;gap:8px}.pg-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pg-card{padding:0;overflow:hidden}.card-image{height:180px;background:linear-gradient(135deg,#dbeafe,#c7d2fe);position:relative}.favorite{position:absolute;right:16px;top:16px;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.9)}.card-body{padding:18px}.price{font-size:1.7rem;font-weight:800}.meta{color:#6b7280}.chip{display:inline-block;background:rgba(79,70,229,.08);font-size:.75rem;font-weight:700;color:#4f46e5;border-radius:999px;padding:6px 10px}@media(max-width:980px){.content-grid,.pg-grid{grid-template-columns:1fr}}</style></head>
<body><div class="page"><div class="search-header"><div class="d-flex justify-content-between align-items-center"><div><div class="text-primary fw-bold">Student Search</div><h1 class="mb-0 mt-2">Find your perfect PG</h1></div><a href="/student" class="btn btn-outline-dark">Dashboard</a></div><p class="mt-3 mb-0 text-secondary">Comfortable stays near your college and workplace.</p><form class="search-form" method="get" action="/student/search"><div class="d-flex align-items-center w-100"><i class="bi bi-geo-alt text-secondary me-2"></i><input name="q" type="text" value="<?= e($query) ?>" placeholder="City, area, or property"></div><input type="hidden" name="gender" value="<?= e($gender) ?>"><input type="hidden" name="room_type" value="<?= e($roomType) ?>"><input type="hidden" name="max_price" value="<?= $maxPrice ?>"><button class="primary-btn" type="submit">Search PG</button></form></div><div class="content-grid"><aside class="filters"><h4 class="mb-3">Filters</h4><form method="get" action="/student/search"><input type="hidden" name="q" value="<?= e($query) ?>"><div class="filter-section"><h6 class="fw-bold">Maximum price</h6><input name="max_price" type="range" class="form-range" min="5000" max="20000" step="500" value="<?= $maxPrice ?: 20000 ?>"><div class="d-flex justify-content-between text-secondary small"><span>₹5,000</span><span>₹20,000</span></div></div><div class="filter-section"><h6 class="fw-bold">Gender</h6><div class="filter-options"><label><input type="radio" name="gender" value="" <?= $gender === '' ? 'checked' : '' ?>> Any</label><label><input type="radio" name="gender" value="male" <?= $gender === 'male' ? 'checked' : '' ?>> Male</label><label><input type="radio" name="gender" value="female" <?= $gender === 'female' ? 'checked' : '' ?>> Female</label><label><input type="radio" name="gender" value="co_living" <?= $gender === 'co_living' ? 'checked' : '' ?>> Co-living</label></div></div><div class="filter-section"><h6 class="fw-bold">Room type</h6><div class="filter-options"><label><input type="radio" name="room_type" value="" <?= $roomType === '' ? 'checked' : '' ?>> Any</label><label><input type="radio" name="room_type" value="single" <?= $roomType === 'single' ? 'checked' : '' ?>> Single</label><label><input type="radio" name="room_type" value="double" <?= $roomType === 'double' ? 'checked' : '' ?>> Double</label><label><input type="radio" name="room_type" value="triple" <?= $roomType === 'triple' ? 'checked' : '' ?>> Triple</label></div></div><button class="btn btn-outline-primary w-100" type="submit">Apply filters</button></form></aside><section class="pg-grid"><?php if (!$pgs): ?><div class="alert alert-light border">No PGs match those filters. Try a wider search.</div><?php endif; ?><?php foreach ($pgs as $pg): ?><article class="pg-card"><div class="card-image"><button type="button" class="favorite border-0" data-favorite="inactive" aria-label="Save property"><i class="bi bi-heart text-danger"></i></button></div><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h4 class="mb-0"><?= e($pg['name']) ?></h4><span class="chip"><?= number_format((float) $pg['rating'], 1) ?> ★</span></div><div class="meta mt-2"><i class="bi bi-geo-alt me-1"></i><?= e($pg['area'] . ', ' . $pg['city']) ?></div><div class="mt-3 text-secondary"><?= e(ucfirst($pg['room_type'])) ?> rooms • <?= e(ucfirst($pg['gender'])) ?></div><div class="price mt-3">₹<?= number_format((float) $pg['price_from'], 0) ?> <span class="fs-6 fw-medium text-secondary">/ month</span></div><div class="mt-3 d-flex justify-content-end"><a class="btn btn-dark" href="/pg-details?id=<?= (int) $pg['id'] ?>">View Details</a></div></div></article><?php endforeach; ?></section></div></div><script src="/assets/js/app.js"></script></body></html>
